import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    static class 子对象 {
        void 打招呼() {
        }

        int 要数据(int 几根) {
            return 几根 * 2;
        }
    }

    public static void main(String[] args) {
        List<String> 函数 = new ArrayList<>();
        for (Method 一个方法 : 子对象.class.getDeclaredMethods()) {
            函数.add(一个方法.getName() + " " + 一个方法.getParameterCount());
        }
        Collections.sort(函数);
        for (String 一行 : 函数) {
            System.out.println(一行);
        }
    }
}

import java.lang.reflect.Field;

public class Main {
    static class 子对象 {
        private String 名字 = "张三";
        private int 数据 = 3;
    }

    public static void main(String[] args) throws Exception {
        子对象 橘 = new 子对象();
        Field 骨头 = 子对象.class.getDeclaredField("数据");
        骨头.setAccessible(true);
        骨头.set(橘, 8);
        System.out.println(骨头.get(橘));
        System.out.println(橘.名字);
    }
}
